<?php namespace Workspace; $b=$botsBinding; $m=$botsMessage; ?>
<section class="panel"><h2>Доставка сообщений CajeerBots</h2><p>Подтвердите точный текст и канал перед постановкой в очередь. Сетевой сбой после начала передачи не является подтверждением недоставки.</p><form method="get" class="inline"><input type="hidden" name="p" value="bots"><label>Проект<select name="project" required><?php selectOptions($botsProjects,$botsProject) ?></select></label><button class="secondary">Открыть</button></form></section>
<?php if($botsProject!==null): ?>
<?php if($botsOwner): ?><section class="panel"><h2>Привязка</h2><p>Цель и выделенный ключ задаются оператором в защищённом файле. Отключение запрещает новые передачи в Bots, но не отменяет уже принятые сообщения.</p><form method="post" class="inline"><?php formFields('bots.binding') ?><input type="hidden" name="project_id" value="<?= (int)$botsProject ?>"><label>Состояние<select name="active"><?php selectOptions(['1'=>'Включить','0'=>'Отключить'],(string)($b['active']??1)) ?></select></label><label><input type="checkbox" name="confirm" value="yes" required> Подтверждаю назначение канала</label><button class="primary">Сохранить (MFA)</button></form></section><?php endif ?>
<?php if(!$b): ?><section class="panel"><p>Нет подключённого канала.</p></section><?php else: ?>
<section class="panel"><h2>Разрешённый канал</h2><p><?= h($b['provider']) ?> · <?= (int)$b['active']?'активен':'отключён' ?> · <code><?= h($b['origin']) ?></code></p><p>Сообщество: <code><?= h($b['community_id']) ?></code> · аккаунт: <code><?= h($b['account_id']) ?></code> · канал: <code><?= h($b['channel_id']) ?></code></p></section>
<?php if($botsManager&&(int)$b['active']): ?><section class="panel"><h2>Подготовить сообщение</h2><p>Для выпуска доступно одно неотменённое сообщение. Вводите только предназначенные для публикации сведения.</p><form method="post" class="formgrid"><?php formFields('bots.draft') ?><input type="hidden" name="project_id" value="<?= (int)$botsProject ?>"><label>Выпуск<select name="release_id"><option value="">Без выпуска</option><?php foreach($botsReleases as $rel): ?><option value="<?= (int)$rel['id'] ?>" <?= $botsSelectedRelease&&(int)$botsSelectedRelease['id']===(int)$rel['id']?'selected':'' ?>><?= h($rel['tag']) ?></option><?php endforeach ?><?php if($botsSelectedRelease&&!in_array((int)$botsSelectedRelease['id'],array_map('intval',array_column($botsReleases,'id')),true)): ?><option selected value="<?= (int)$botsSelectedRelease['id'] ?>"><?= h($botsSelectedRelease['tag']) ?></option><?php endif ?></select></label><label>Сообщение<textarea name="message" rows="8" maxlength="2000" required><?= $botsSelectedRelease?h('Выпуск '.$botsSelectedRelease['tag']):'' ?></textarea></label><button class="primary">Сохранить предпросмотр</button></form></section><?php endif ?>
<section class="panel"><h2>Сообщения</h2><div class="tablewrap"><table><thead><tr><th>ID</th><th>Выпуск</th><th>Статус</th><th>UTC</th></tr></thead><tbody><?php foreach($botsMessages as $r): ?><tr><td><a href="<?= h(url('bots',['project'=>$botsProject,'id'=>$r['id']])) ?>">#<?= (int)$r['id'] ?></a></td><td><?php if($r['release_id']!==null): ?><a href="<?= h(url('releases',['project'=>$botsProject,'id'=>$r['release_id']])) ?>">#<?= (int)$r['release_id'] ?></a><?php else: ?>—<?php endif ?></td><td><?= h($r['state']) ?></td><td><?= h(gmdate('Y-m-d H:i:s',(int)$r['created_at'])) ?></td></tr><?php endforeach ?></tbody></table></div></section>
<?php if($m): ?><section class="panel"><h2>Предпросмотр #<?= (int)$m['id'] ?> — <?= h($m['state']) ?></h2><p>Канал: <code><?= h($b['channel_id']) ?></code> · редакция аккаунта: <?= h($m['target_revision']) ?></p><pre class="release-text"><?= h($m['message']) ?></pre><p>SHA-256 текста: <code><?= h($m['message_hash']) ?></code></p><p>Снимок подтверждения: <code><?= h($m['preview_hash']) ?></code></p><p>Удалённый ID: <code><?= h($m['remote_id']) ?></code> · попыток провайдера: <?= (int)$m['remote_attempts'] ?> · ID сообщения: <?= h($m['provider_message_id']??'—') ?> · <?= h($m['error_code']) ?></p>
<?php if($botsManager): $ops=[];$state=$m['state'];if($state==='draft'&&(int)$b['active'])$ops['confirm']='Подтвердить точный текст и канал';if(($state==='failed'&&$m['command']==='create'||$state==='retryable'&&(int)$m['remote_attempts']<8)&&(int)$b['active'])$ops['retry']='Повторить после отказа до отправки';if(in_array($state,['draft','failed','pending','retryable'],true)||$state==='queued'&&in_array($m['command'],['create','retry'],true))$ops['cancel']='Отменить до начала отправки';if(in_array($state,['pending','sending','retryable','uncertain'],true))$ops['check']='Сверить точный ID в Bots';if($state==='uncertain')$ops['close']='Закрыть без подтверждения доставки (без повтора)';foreach($ops as $op=>$title): ?><form method="post" class="inline"><?php formFields('bots.'.$op) ?><input type="hidden" name="project_id" value="<?= (int)$botsProject ?>"><input type="hidden" name="id" value="<?= (int)$m['id'] ?>"><input type="hidden" name="preview_hash" value="<?= h($m['preview_hash']) ?>"><label><input type="checkbox" name="confirm" value="yes" required> <?= h($title) ?></label><button class="secondary">Выполнить (MFA)</button></form><?php endforeach;endif ?>
<h3>История</h3><div class="tablewrap"><table><thead><tr><th>UTC</th><th>Состояние</th><th>Операция</th><th>Участник</th></tr></thead><tbody><?php foreach($botsEvents as $ev): ?><tr><td><?= h(gmdate('Y-m-d H:i:s',(int)$ev['created_at'])) ?></td><td><?= h($ev['state']) ?></td><td><?= h($ev['detail']) ?></td><td>#<?= (int)$ev['actor_id'] ?></td></tr><?php endforeach ?></tbody></table></div></section><?php endif ?>
<?php endif;endif ?>
